{
  "page_issues": [
    {
      "page": "A) 今日作业页 (/)",
      "issues": [
        {
          "title": "核心功能入口文案冗余",
          "symptom": "按钮文案“生成今日作业并打印（孩子不接触屏幕）”在手机屏占两行，且强调过多。",
          "fix": "改为“生成今日默写纸”或“打印今日作业”。副标题用小字提示“含新词+复习”。",
          "priority": 2
        },
        {
          "title": "待录入错题入口不明显",
          "symptom": "如果“待录入错题”是文本链接，家长手指粗大容易误触或忽略。",
          "fix": "改为卡片式设计或底部悬浮栏：“您有 N 个错题待录入”，点击直接进入录入模式。",
          "priority": 1
        }
      ]
    },
    {
      "page": "B) 作业列表/提取页 (/worksheets)",
      "issues": [
        {
          "title": "文本粘贴区高度不足",
          "symptom": "手机软键盘弹出后，textarea 仅剩 1-2 行可见，无法检查粘贴内容全貌。",
          "fix": "设置 textarea `min-height: 30vh`，或在键盘弹出时自动滚动页面至输入区顶部。",
          "priority": 2
        },
        {
          "title": "生词勾选列表点击热区过小",
          "symptom": "提取出的单词列表，复选框太小，家长单手操作容易点错。",
          "fix": "扩大点击热区：点击整行（单词+释义）均可触发勾选/取消勾选。增加选中态背景色高亮。",
          "priority": 1
        }
      ]
    },
    {
      "page": "C) 试卷详情页 (/worksheets/{id})",
      "issues": [
        {
          "title": "题型一（表格）手机端横向溢出",
          "symptom": "中译英表格在竖屏下必定超出屏幕，导致页面出现双向滚动条，体验极差。",
          "fix": "移动端视图下（非打印态），将表格改为“卡片列表”：中文在上，英文（答案）在下（默认隐藏，点击显示）。打印态保持表格。",
          "priority": 0
        },
        {
          "title": "题型二（选择）两列布局拥挤",
          "symptom": "长单词（如 'encyclopedia'）会导致两列布局错位或文字折行严重。",
          "fix": "移动端视图强制单列 (`grid-template-columns: 1fr`)；打印态保持双列但缩小字号。",
          "priority": 1
        },
        {
          "title": "打印分页逻辑浪费纸张",
          "symptom": "`.worksheet-break` 强制每个大区分页，若题型三只有 2 句话，也会独占一张 A4 纸。",
          "fix": "移除强制分页。改用 CSS `break-inside: avoid` 作用于每个“题块（Question Block）”，仅在页面空间不足时自动换页。",
          "priority": 0
        },
        {
          "title": "缺乏“批改模式”视图",
          "symptom": "家长拿着纸质作业核对时，手机屏幕上同时显示题目和答案，视线跳跃累。",
          "fix": "增加顶部开关“批改模式”：开启后，隐藏题目描述，仅高亮显示“序号 + 英文答案 + 中文核心义”，方便快速对答案。",
          "priority": 2
        }
      ]
    },
    {
      "page": "E) 词书库与组件 (/decks)",
      "issues": [
        {
          "title": "Deck Picker 下拉菜单被遮挡",
          "symptom": "在弹窗或底部操作栏中选择词书时，下拉列表被父容器 `overflow: hidden` 裁切或被键盘顶出屏幕。",
          "fix": "移动端禁用自定义下拉模拟，改用原生 `<select>` 标签（iOS/Android 原生体验最好），或使用全屏 Modal/Bottom Sheet 选择器。",
          "priority": 1
        }
      ]
    }
  ],
  "worksheet_layout_options": {
    "economy": {
      "sections": [
        "紧凑模式：标题与姓名栏并排",
        "题型一：仅保留【中文】与【拼写格】，去除序号列，行高压缩",
        "题型二：选项由卡片改为纯文本紧凑排列（a. xxx b. xxx）",
        "题型三：填空题接排，不换行"
      ],
      "page_break_rules": [
        "禁止大区强制分页",
        "允许题目在页面底部截断（最大化利用纸张）",
        "字体：10pt / 行高 1.2"
      ],
      "typography": [
        "无衬线字体 (Arial/Heiti)",
        "减少页边距至 10mm"
      ]
    },
    "standard": {
      "sections": [
        "标准试卷头（学校风格）：包含 班级/姓名/学号/日期/得分 栏",
        "题型一：标准三列表格（序号/中文/四线三格拼写区）",
        "题型二：带边框的选项卡片，双列对齐",
        "题型三：独立段落"
      ],
      "page_break_rules": [
        "大题之间尽量不分页（除非空间极小）",
        "单个小题（Question Item）内部绝对禁止分页 (`break-inside: avoid`)",
        "字体：12pt / 行高 1.5"
      ],
      "typography": [
        "衬线字体 (Times New Roman/Songti) 增加正式感",
        "标准页边距 25.4mm"
      ]
    }
  },
  "mobile_css_changes": [
    "@media screen and (max-width: 600px) { .worksheet-table { display: block; } .worksheet-table tr { display: flex; flex-direction: column; border-bottom: 1px solid #eee; padding: 8px 0; } }",
    "@media screen and (max-width: 600px) { .worksheet-table td, .worksheet-table th { display: block; width: 100%; border: none; padding: 2px 0; } }",
    "@media screen and (max-width: 600px) { .worksheet-q-choices { grid-template-columns: 1fr !important; gap: 8px; } }",
    "@media print { nav, .btn-float, .grading-tools, .footer { display: none !important; } }",
    "@media print { body { background: white; color: black; font-size: 12pt; } .worksheet-container { box-shadow: none; margin: 0; width: 100%; } }",
    "@media print { .worksheet-section { page-break-inside: avoid; margin-bottom: 20px; } }",
    ".deck-picker-mobile { appearance: none; background-color: transparent; width: 100%; height: 44px; position: absolute; opacity: 0; z-index: 10; }",
    ".checkbox-row { display: flex; align-items: center; padding: 12px 0; min-height: 44px; } /* 增大点击热区 */",
    ".worksheet-preview { overflow-x: hidden; padding: 10px; } /* 防止整体横向滚动 */"
  ],
  "acceptance_tests": [
    "iPhone SE 尺寸下，首页“生成作业”按钮是否完整显示且易点击。",
    "粘贴 500 字文本后，软键盘弹出时，是否仍能看到光标和至少 2 行文本。",
    "在手机端查看试卷详情，表格题是否不再出现横向滚动条（已转为列表/卡片视图）。",
    "点击“打印”按钮调用系统打印预览，确认 3 种题型是否混排在同一页（省纸），而非强制分 3 页。",
    "打印预览中，长单词（如 congratulations）在选择题选项中是否被截断。",
    "点击单词提取列表的文字部分（非 checkbox），确认能否触发勾选。",
    "在底部导航栏快速切换 Tab，确认不会出现页面闪烁或布局错位。",
    "模拟录入错题：在输入框输入时，确认“保存”按钮没有被键盘遮挡。",
    "检查“批改模式”下，是否能一眼看清所有答案，无需频繁滑动屏幕。"
  ]
}

